 "content": "def transform(grid):
    """Extend each side of the solid 2 rectangle to the grid edge until 1 markers."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    if not cells:
        return out
    r0 = min(r for r, c in cells)
    r1 = max(r for r, c in cells)
    c0 = min(c for r, c in cells)
    c1 = max(c for r, c in cells)
    # For each row/column of the rectangle, extend independently in each direction;
    # a 1 in the path blocks that extension and is preserved.
    for r in range(r0, r1 + 1):
        for dc in (-1, 1):
            c = c0 - 1 if dc < 0 else c1 + 1
            while 0 <= c < w and grid[r][c] != 1:
                out[r][c] = 2
                c += dc
    for c in range(c0, c1 + 1):
        for dr in (-1, 1):
            r = r0 - 1 if dr < 0 else r1 + 1
            while 0 <= r < h and grid[r][c] != 1:
                out[r][c] = 2
                r += dr
    return out
